import React, { useState } from 'react';
import { uploadResume } from '../../services/api';
import './ResumeUploader.css';

const allowedExtensions = ['.pdf', '.docx'];
const maxFileSize = 5 * 1024 * 1024;

/**
 * Component responsible for selecting and uploading a resume file.
 */
const ResumeUploader = () => {
  const [selectedFile, setSelectedFile] = useState(null);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [status, setStatus] = useState({ type: 'idle', message: '' });
  const [isUploading, setIsUploading] = useState(false);

  const handleFileChange = (event) => {
    const file = event.target.files?.[0];

    if (!file) {
      return;
    }

    const extension = file.name.slice(file.name.lastIndexOf('.')).toLowerCase();

    if (!allowedExtensions.includes(extension)) {
      setStatus({ type: 'error', message: 'Only PDF and DOCX files are supported.' });
      setSelectedFile(null);
      return;
    }

    if (file.size > maxFileSize) {
      setStatus({ type: 'error', message: 'File size must be 5MB or less.' });
      setSelectedFile(null);
      return;
    }

    setSelectedFile(file);
    setStatus({ type: 'idle', message: `${file.name} is ready to upload.` });
    setUploadProgress(0);
  };

  const handleUpload = async () => {
    if (!selectedFile) {
      setStatus({ type: 'error', message: 'Please choose a valid resume file first.' });
      return;
    }

    const formData = new FormData();
    formData.append('resume', selectedFile);

    setIsUploading(true);
    setUploadProgress(0);
    setStatus({ type: 'info', message: 'Uploading resume...' });

    try {
      const response = await uploadResume(formData, {
        onUploadProgress: (event) => {
          const percent = Math.round((event.loaded * 100) / event.total);
          setUploadProgress(percent);
        }
      });

      setStatus({ type: 'success', message: response.data.message || 'Resume uploaded successfully.' });
    } catch (error) {
      setStatus({
        type: 'error',
        message: error.response?.data?.message || 'Upload failed. Please try again.'
      });
    } finally {
      setIsUploading(false);
    }
  };

  return (
    <div className="resume-uploader">
      <h2>Upload Resume</h2>
      <p>Upload a PDF or DOCX resume to begin analysis.</p>

      <label className="resume-uploader__label" htmlFor="resume-file">
        Choose file
      </label>
      <input id="resume-file" type="file" accept=".pdf,.docx" onChange={handleFileChange} />

      {selectedFile && (
        <p className="resume-uploader__file-name">
          Selected: <strong>{selectedFile.name}</strong>
        </p>
      )}

      <button className="resume-uploader__button" onClick={handleUpload} disabled={isUploading}>
        {isUploading ? 'Uploading...' : 'Upload Resume'}
      </button>

      {isUploading && (
        <div className="resume-uploader__progress" aria-label="upload progress">
          <div className="resume-uploader__progress-bar" style={{ width: `${uploadProgress}%` }} />
        </div>
      )}

      {status.message && (
        <p className={`resume-uploader__status resume-uploader__status--${status.type}`}>{status.message}</p>
      )}
    </div>
  );
};

export default ResumeUploader;
